@page "/apply"
@using sv_a8845bfeb0e54c9cb63b64e1682eadfe.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 1:
                <PersonalInfoStep Model="personalInfo"
                                  Errors="errors"
                                  IsValidating="isValidatingEmail"
                                  OnNext="HandleNextFromStep1" />
                break;
            case 2:
                <WorkHistoryStep Entries="workEntries"
                                 Errors="errors"
                                 OnNext="HandleNext"
                                 OnBack="HandleBack" />
                break;
            case 3:
                <ReferencesStep References="references"
                                Errors="errors"
                                OnNext="HandleNext"
                                OnBack="HandleBack" />
                break;
            case 4:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 CoverLetterChanged="val => coverLetter = val"
                                 Errors="errors"
                                 OnNext="HandleNext"
                                 OnBack="HandleBack" />
                break;
            case 5:
                <ReviewStep Personal="personalInfo"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="@coverLetter"
                            IsSubmitting="isSubmitting"
                            SubmittedId="submittedId"
                            SubmitError="@submitError"
                            OnEdit="GoToStep"
                            OnSubmit="HandleSubmit"
                            OnBack="HandleBack" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = [];
    private Dictionary<string, string> errors = [];
    private bool isValidatingEmail;
    private bool isSubmitting;
    private int? submittedId;
    private string? submitError;

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        errors.Clear();
        currentStep = step;
    }

    private void HandleBack()
    {
        errors.Clear();
        currentStep--;
    }

    private async Task HandleNextFromStep1()
    {
        if (!ValidateStep1()) return;

        isValidatingEmail = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
            if (!isValid)
            {
                errors["Email"] = "This email address is not valid.";
                return;
            }
        }
        finally
        {
            isValidatingEmail = false;
        }

        AdvanceStep();
    }

    private void HandleNext()
    {
        if (!ValidateCurrentStep()) return;
        AdvanceStep();
    }

    private void AdvanceStep()
    {
        completedSteps.Add(currentStep);
        errors.Clear();
        currentStep++;
    }

    private bool ValidateCurrentStep() => currentStep switch
    {
        1 => ValidateStep1(),
        2 => ValidateStep2(),
        3 => ValidateStep3(),
        4 => ValidateStep4(),
        _ => true
    };

    private bool ValidateStep1()
    {
        errors.Clear();
        if (string.IsNullOrWhiteSpace(personalInfo.FullName))
            errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(personalInfo.Email))
            errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(personalInfo.Phone))
            errors["Phone"] = "Phone number is required.";
        if (string.IsNullOrWhiteSpace(personalInfo.Address))
            errors["Address"] = "Address is required.";
        return errors.Count == 0;
    }

    private bool ValidateStep2()
    {
        errors.Clear();
        for (int i = 0; i < workEntries.Count; i++)
        {
            var e = workEntries[i];
            var idx = i + 1;
            if (string.IsNullOrWhiteSpace(e.Company))
                errors[$"{idx}.Company"] = "Company is required.";
            if (string.IsNullOrWhiteSpace(e.Title))
                errors[$"{idx}.Title"] = "Job title is required.";
            if (!e.StartDate.HasValue)
                errors[$"{idx}.StartDate"] = "Start date is required.";
        }
        return errors.Count == 0;
    }

    private bool ValidateStep3()
    {
        errors.Clear();
        for (int i = 0; i < references.Count; i++)
        {
            var r = references[i];
            var idx = i + 1;
            if (string.IsNullOrWhiteSpace(r.Name))
                errors[$"{idx}.Name"] = "Name is required.";
            if (string.IsNullOrWhiteSpace(r.Relationship))
                errors[$"{idx}.Relationship"] = "Relationship is required.";
            if (string.IsNullOrWhiteSpace(r.Email))
                errors[$"{idx}.Email"] = "Email is required.";
            if (string.IsNullOrWhiteSpace(r.Phone))
                errors[$"{idx}.Phone"] = "Phone is required.";
        }
        return errors.Count == 0;
    }

    private bool ValidateStep4()
    {
        errors.Clear();
        if (string.IsNullOrWhiteSpace(coverLetter))
            errors["CoverLetter"] = "Cover letter is required.";
        return errors.Count == 0;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate!.Value,
                    e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            var id = await ApplicationService.SubmitApplicationAsync(application);
            submittedId = id;
            completedSteps.Add(5);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

::deep .last-no-border:last-child {
    border-bottom: none !important;
    margin-bottom: 0 !important;
    padding-bottom: 0 !important;
}

