+                    e.Company, e.Title, e.StartDate!.Value,
+                    e.IsCurrent ? null : e.EndDate, e.Description
+                )).ToList()),
+                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+                coverLetter
+            );
+
+            var id = await ApplicationService.SubmitApplicationAsync(application);
+            submittedId = id;
+            completedSteps.Add(5);
+        }
+        catch (Exception ex)
+        {
+            submitError = $"Submission failed: {ex.Message}. Please try again.";
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+}
